from queueing import payload

def submit(owner, enqueue, region="worldwide"):
    return enqueue(payload(owner, region))

def execute(task, collect, region="worldwide"):
    if region not in ["worldwide", "europe", "americas"]:
        raise ValueError("Invalid region. Allowed values are: worldwide, europe, americas")
    return collect(task["owner"], region)

import api, queueing, worker
from queueing import payload
from worker import execute

# Test API submit
def test_submit():
    def mock_enqueue(task):
        return task

    # Test with default region (should be worldwide)
    result = api.submit("owner1", mock_enqueue)
    assert result == {"owner": "owner1"}

    # Test with explicit region
    result = api.submit("owner2", mock_enqueue, region="europe")
    assert result == {"owner": "owner2", "region": "europe"}

    # Test invalid region raises ValueError (from worker side)
    def mock_enqueue_invalid(task):
        def mock_collect(_, region):
            raise ValueError("Invalid region")
        return execute(task, mock_collect, region="invalid")

    try:
        api.submit("owner3", mock_enqueue_invalid, region="invalid")
        assert False, "Expected ValueError for invalid region"
    except ValueError as e:
        assert str(e) == "Invalid region. Allowed values are: worldwide, europe, americas"

# Test queueing payload
def test_payload():
    # Test default region
    result = payload("owner1")
    assert result == {"owner": "owner1", "region": "worldwide"}

    # Test explicit region
    result = payload("owner2", region="americas")
    assert result == {"owner": "owner2", "region": "americas"}

    # Test legacy (no region) still uses worldwide
    result = payload("owner3")
    assert result == {"owner": "owner3", "region": "worldwide"}

# Test worker execution
def test_worker_execute():
    def mock_collect(owner, region):
        return (owner, region)

    # Test default region
    result = execute({"owner": "owner1"}, mock_collect)
    assert result == ("owner1", "worldwide")

    # Test explicit region
    result = execute({"owner": "owner2"}, mock_collect, region="europe")
    assert result == ("owner2", "europe")

    # Test invalid region raises ValueError
    try:
        execute({"owner": "owner3"}, mock_collect, region="invalid")
        assert False, "Expected ValueError for invalid region"
    except ValueError as e:
        assert str(e) == "Invalid region. Allowed values are: worldwide, europe, americas"
